-- NVIDIA Auto-Ontology / PostgreSQL Industrial Manufacturing Schema
-- Enterprise MES/YMS Aligned 6-Pillar Architecture:
-- 1. Fab & Environmental Baseline (dim_fab)
-- 2. Material & Chemical Properties (dim_material_spec)
-- 3. Product Model & Cell Geometry (dim_product_model)
-- 4. Process Route & Sequencing (dim_process_route, dim_process_layer, dim_route_step)
-- 5. Equipment Hardware Topology & Recipe (dim_equipment, dim_recipe)
-- 6. Defect Classification, Incidents & Actions (dim_defect_type, fact_defect_incident, fact_root_cause_action)
-- Generated by knowhow-miner (v1.7.0)

-- 1. Fab / Manufacturing Facility Dimension
CREATE TABLE IF NOT EXISTS dim_fab (
    fab_id VARCHAR(64) PRIMARY KEY,
    fab_name VARCHAR(128) NOT NULL,
    generation VARCHAR(32) NOT NULL,          -- e.g. G5.5, G6, G8.5
    substrate_size_mm VARCHAR(64) NOT NULL,    -- e.g. 1300x1500, 1500x1850, 2200x2500
    display_tech VARCHAR(64) NOT NULL,         -- e.g. LTPS-LCD, Flexible AMOLED, Oxide-TFT
    cleanroom_class VARCHAR(32) DEFAULT 'Class 10',
    temp_target_c NUMERIC DEFAULT 23.0,
    humidity_target_pct NUMERIC DEFAULT 45.0,
    vibration_criteria VARCHAR(32) DEFAULT 'VC-C'
);

-- 2. Material & Chemical Properties
CREATE TABLE IF NOT EXISTS dim_material_spec (
    material_id VARCHAR(64) PRIMARY KEY,
    material_name VARCHAR(128) NOT NULL,
    material_category VARCHAR(64) NOT NULL,    -- e.g. Photoresist, Developer, Stripper, Target, Glass
    viscosity_cp NUMERIC,                      -- e.g. 5.5, 23.0 for thick organic films
    solid_content_pct NUMERIC,
    solvent_type VARCHAR(64),
    storage_temp_c NUMERIC,
    vendor VARCHAR(64)
);

-- 3. Product Model & Cell Geometry
CREATE TABLE IF NOT EXISTS dim_product_model (
    product_id VARCHAR(64) PRIMARY KEY,
    product_name VARCHAR(128) NOT NULL,
    resolution VARCHAR(64),
    display_size_inch NUMERIC,
    ppi NUMERIC,
    display_tech VARCHAR(64) NOT NULL,
    fab_generation VARCHAR(32) NOT NULL,
    fab_id VARCHAR(64) REFERENCES dim_fab(fab_id)
);

-- 4. Process Route Flow
CREATE TABLE IF NOT EXISTS dim_process_route (
    route_id VARCHAR(64) PRIMARY KEY,
    route_name VARCHAR(128) NOT NULL,
    mask_count INTEGER NOT NULL,
    product_id VARCHAR(64) REFERENCES dim_product_model(product_id),
    is_active BOOLEAN DEFAULT TRUE
);

-- 5. Film Layer Dimension
CREATE TABLE IF NOT EXISTS dim_process_layer (
    layer_id VARCHAR(32) PRIMARY KEY,
    layer_name VARCHAR(64) NOT NULL,
    material_id VARCHAR(64) REFERENCES dim_material_spec(material_id),
    thickness_spec_nm NUMERIC,
    is_thick_film BOOLEAN DEFAULT FALSE
);

-- 6. Route Operation Step
CREATE TABLE IF NOT EXISTS dim_route_step (
    step_id VARCHAR(64) PRIMARY KEY,
    route_id VARCHAR(64) REFERENCES dim_process_route(route_id),
    step_seq INTEGER NOT NULL,
    step_name VARCHAR(128) NOT NULL,
    layer_id VARCHAR(32) REFERENCES dim_process_layer(layer_id),
    station_type VARCHAR(64) NOT NULL          -- e.g. PHOTO, ETCH, CVD, CLEAN, INSPECTION
);

-- 7. Equipment Hardware Topology
CREATE TABLE IF NOT EXISTS dim_equipment (
    equipment_id VARCHAR(64) PRIMARY KEY,
    equipment_name VARCHAR(128) NOT NULL,
    equipment_group VARCHAR(64) NOT NULL,      -- e.g. Track, Stepper, Cleaner, DryEtcher
    sub_unit VARCHAR(64) NOT NULL,             -- e.g. Slit Coater, Air Knife, Hot Plate, Exposure Lens
    vendor VARCHAR(64),
    fab_id VARCHAR(64) REFERENCES dim_fab(fab_id),
    fab_line VARCHAR(64)
);

-- 8. Machine Recipe Parameters
CREATE TABLE IF NOT EXISTS dim_recipe (
    recipe_id VARCHAR(64) PRIMARY KEY,
    recipe_name VARCHAR(128) NOT NULL,
    equipment_id VARCHAR(64) REFERENCES dim_equipment(equipment_id),
    step_id VARCHAR(64) REFERENCES dim_route_step(step_id),
    dose_mj NUMERIC,
    focus_offset_um NUMERIC,
    temperature_c NUMERIC,
    flow_rate_lmin NUMERIC,
    scan_speed_mms NUMERIC,
    recipe_version VARCHAR(32) DEFAULT 'v1.0'
);

-- 9. Defect Type Dimension
CREATE TABLE IF NOT EXISTS dim_defect_type (
    defect_code VARCHAR(64) PRIMARY KEY,
    defect_name_zh VARCHAR(128) NOT NULL,
    defect_category VARCHAR(64) NOT NULL,      -- e.g. Mura, Particle, Pattern_Deform, Crack, CD_OOC
    manifest_station VARCHAR(64)
);

-- 10. Defect Incident Fact Table
CREATE TABLE IF NOT EXISTS fact_defect_incident (
    incident_id SERIAL PRIMARY KEY,
    lot_id VARCHAR(64),
    occurred_date DATE NOT NULL,
    fab_id VARCHAR(64) REFERENCES dim_fab(fab_id),
    product_id VARCHAR(64) REFERENCES dim_product_model(product_id),
    step_id VARCHAR(64) REFERENCES dim_route_step(step_id),
    recipe_id VARCHAR(64) REFERENCES dim_recipe(recipe_id),
    equipment_id VARCHAR(64) REFERENCES dim_equipment(equipment_id),
    layer_id VARCHAR(32) REFERENCES dim_process_layer(layer_id),
    defect_code VARCHAR(64) REFERENCES dim_defect_type(defect_code),
    impact_yield_loss_pct NUMERIC,
    scrap_sheet_count INTEGER,
    detect_station VARCHAR(64),
    source_evidence_title VARCHAR(255)
);

-- 11. Root Cause & Action Fact Table
CREATE TABLE IF NOT EXISTS fact_root_cause_action (
    action_id SERIAL PRIMARY KEY,
    incident_id INTEGER REFERENCES fact_defect_incident(incident_id),
    root_cause_physical TEXT NOT NULL,
    target_unit VARCHAR(64) NOT NULL,
    param_name VARCHAR(64),
    param_unit VARCHAR(32),
    param_before VARCHAR(64),
    param_after VARCHAR(64),
    countermeasure_summary TEXT NOT NULL,
    verification_status VARCHAR(64) NOT NULL,
    report_doc_name VARCHAR(255)
);
